  //   ledcSetFrequency(0, frequency, resolution);
  //   ledcSetFrequency(1, frequency, resolution);
  //   ledcAttachPin(pinA, 0);
  //   ...
}

void SpaceVectorPWM::updateAlpha(float alpha, float beta)
{
  // Braço superior
  upperArm.setDuty(alpha * _halfDuty + _halfDuty, beta * _halfDuty + _halfDuty, 0.0f);
  // Braço inferior recebe o resto da largura de pulso
  float dc = _maxDuty - (alpha * _halfDuty + _halfDuty) -
              (beta * _halfDuty + _halfDuty);
  lowerArm.setDuty(alpha * _halfDuty + _halfDuty, beta * _halfDuty + _halfDuty, dc);
}

void SpaceVectorPWM::setDeadTime(unsigned long ms)
{
  _defaultDeadTimeMs = ms;
}

/* --------------------------------------------------------------
   Classe Arm – implementação detalhada do deadtime
   -------------------------------------------------------------- */
Arm::Arm(uint8_t pinA_, uint8_t pinB_, uint8_t pinC)
    : pinA_(pinA_), pinB_(pinB_), pinC_(pinC)
{
}

void Arm::setDuty(float dA, float dB, float dc = 0.0f)
{
  dutyA = dA;
  dutyB = dB;
  dutyC = dc;
  // --- DEADTIME LOGIC ---
  // Se o switch que será desligado agora já estava ligado, precisamos esperar o deadtime.
  // Para simplicidade, verificamos apenas o estado atual dos switches.
  // Aqui guardamos os últimos momentos de desligamento e comparamos com o tempo atual.
  // (Na prática, você faria isso dentro de um loop de PWM.)
  // Exemplo rápido: se lastOffA > 0 e não estamos no momento exato de transição,
  // adicionamos o deadtime.
  //
