  //   Se lastOffA == 0, então o switch A acabou de ser desligado; agora podemos
  //   habilitar o switch B após deadTimeMs.
  // Para manter o código funcional, deixamos o deadtime como campo e o usuário
  // deve chamá-lo antes de aplicar o novo duty.
  // --------------------
}

void Arm::run()
{
  // Este método seria chamado a cada ciclo de PWM.
  // Aqui você poderia gerar os sinais de saída e aplicar o deadtime.
  // Para ESP32, basta usar `analogWrite(pin, duty * 255)`.
}

/* --------------------------------------------------------------
   Classe SpaceVectorPWM – métodos auxiliares
   -------------------------------------------------------------- */
SpaceVectorPWM::SpaceVectorPWM() {}

void SpaceVectorPWM::begin(float frequency, uint8_t resolution)
{
  // Exemplo usando Arduino's built-in PWM (funcionamento básico)
  // Você pode substituir por ledcSetFrequency() se preferir.
  // AnalogWrite(PIN_A, (uint16)(dutyA * 255)); // aqui seria atualizado a cada ciclo
}

void SpaceVectorPWM::updateAlpha(float alpha, float beta)
{
  // Chama o método acima
  upperArm.setDuty(alpha * _halfDuty + _halfDuty, beta * _halfDuty + _halfDuty, 0.0f);
  lowerArm.setDuty(alpha * _halfDuty + _halfDuty, beta * _halfDuty + _halfDuty, _maxDuty - (alpha * _halfDuty + _halfDuty) -
                            (beta * _halfDuty + _halfDuty));
}

void SpaceVectorPWM::setDeadTime(unsigned long ms)
{
